  "check_code": "import hashlib
import json
import sqlite3
from datetime import datetime
from pathlib import Path


CASE_ID = "CASE-SYQ-NOISE-2025-0516"
BASELINE_ACTION_IDS = {f"ACT-SYQ-0516-{index:02d}" for index in range(1, 7)}
LAST_BASELINE_ACTION_AT = datetime(2025, 5, 27, 16, 20, 0)
REQUIRED_EVIDENCE = (
    "苏右风电场噪声治理效果验收记录.xlsx",
    "20250526升压站厂界噪声复测明细.csv",
    "1号主变冷却系统降噪整改实施单.docx",
)

BASELINE_HISTORY = {
    "ACT-SYQ-0516-01": ("PER-SYQ-MJY", "investigation", "2025-05-19 09:20:00", "valid", "INV_SCOPE_CONFIRMED", None, "确认复核期间为2025-05-19至2025-05-26，覆盖升压站四周厂界、1号主变冷却系统及李军家敏感点。"),
    "ACT-SYQ-0516-02": ("PER-SYQ-ZWB", "diagnosis", "2025-05-26 17:10:00", "valid", "SOURCE_RECTIFICATION_REQUIRED", None, "结合风机和1号主变运行工况、风速风向、厂界Leq及背景噪声修正值，形成噪声源诊断报告，要求复核冷却风机减振和隔声设施。"),
    "ACT-SYQ-0516-03": ("PER-SYQ-ZWB", "rectification_handoff", "2025-05-26 17:35:00", "valid", "RECTIFICATION_ASSIGNED", None, "整改移交检修组，内容包括1号主变冷却系统减振件、风道连接和降噪设施运行状态复核。"),
    "ACT-SYQ-0516-04": ("PER-SYQ-CSY", "acceptance_handoff", "2025-05-27 15:40:00", "valid", "TECHNICAL_ACCEPTANCE_READY", None, "验收材料已移交：监测点位、原始记录、声级计校准记录、设备工况证明、超标点位及整改复测结论齐备，技术上具备销号条件。"),
    "ACT-SYQ-0516-05": ("PER-SYQ-MJY", "closure_submit", "2025-05-27 16:00:00", "cancelled", "CLOSURE_SUBMITTED_EARLY", None, "早期销号提交因验收附件索引不完整撤回。"),
    "ACT-SYQ-0516-06": ("PER-SYQ-MJY", "closure_submit", "2025-05-27 16:20:00", "valid", "CLOSURE_PENDING_APPROVAL", "ACT-SYQ-0516-05", "补齐验收附件索引后重新提交行政销号审批，当前行政状态仍为验收流程。"),
}

UNRELATED_DIGESTS = {
    "other_cases": (26, "ae3473631012c50979034fae75784af173b4ecd27f3fd154efdc3914759a6a92"),
    "other_actions": (118, "50e22e0d2d55e575de66f92a099d8c0e8812a1756e421f637954849a3ff19ec4"),
    "assignments": (67, "553880e0e4ce4448b1528f8c96b544ad36bb728e5354bb9500dfe9515e692449"),
    "personnel": (36, "01747c8ac308117915e7cd20329793b7fa8b7652a3da49babff79b36abe663fc"),
}


def _db_path(ws):
    return Path(ws).resolve().parent / "system" / "cgn_ehs_case" / "state.db"


def _connect(ws):
    connection = sqlite3.connect(_db_path(ws))
    connection.row_factory = sqlite3.Row
    return connection


def _parse_time(value):
    return datetime.strptime(value, "%Y-%m-%d %H:%M:%S")


def _normalize_text(value):
    text = str(value or "").casefold()
    for character in " \\/_-—–·《》〈〉[]【】()（）；;，,。.：:｜|":
        text = text.replace(character, "")
    return text


def _new_submission_rows(connection):
    rows = connection.execute(
        "SELECT * FROM case_actions WHERE case_id = ? ORDER BY action_at, action_id",
        (CASE_ID,),
    ).fetchall()
    return [row for row in rows if row["action_id"] not in BASELINE_ACTION_IDS]


def _digest_rows(connection, sql, params=()):
    rows = [dict(row) for row in connection.execute(sql, params)]
    payload = json.dumps(rows, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return len(rows), hashlib.sha256(payload.encode("utf-8")).hexdigest()


def check_new_valid_closure_submit(ws):
    with _connect(ws) as connection:
        new_rows = _new_submission_rows(connection)
    if len(new_rows) != 1:
        return {"score": 0, "detail": f"基线六条动作之外应恰好新增1条，实际新增{len(new_rows)}条"}
    row = new_rows[0]
    expected = {
        "action_type": "closure_submit",
        "action_status": "valid",
        "conclusion_code": "CLOSURE_PENDING_APPROVAL",
    }
    mismatches = [f"{key}={row[key]!r}" for key, value in expected.items() if row[key] != value]
    try:
        is_later = _parse_time(row["action_at"]) > LAST_BASELINE_ACTION_AT
    except (TypeError, ValueError):
        is_later = False
    if mismatches or not is_later:
        detail = "，".join(mismatches) or "动作时间不晚于既有最新提交"
        return {"score": 0, "detail": detail}
    return {"score": 1, "detail": f"新增有效行政销号提交：{row['action_id']}"}


def check_closure_evidence_complete(ws):
    with _connect(ws) as connection:
        new_rows = _new_submission_rows(connection)
    if len(new_rows) != 1:
        return {"score": 0, "detail": "无法唯一定位新增销号提交动作"}
    note = _normalize_text(new_rows[0]["action_note"])
    missing = [name for name in REQUIRED_EVIDENCE if _normalize_text(name) not in note]
    if missing:
        return {"score": 0, "detail": "新增动作缺少证据引用：" + "、".join(missing)}
    return {"score": 1, "detail": "新增动作已关联验收记录、复测原始记录和整改实施单"}


def check_case_pending_not_closed(ws):
    with _connect(ws) as connection:
        row = connection.execute(
            "SELECT case_status FROM noise_cases WHERE case_id = ?",
            (CASE_ID,),
        ).fetchone()
    if row is None:
        return {"score": 0, "detail": "目标投诉不存在"}
    if row["case_status"] != "closure_pending":
        return {"score": 0, "detail": f"目标投诉状态为{row['case_status']!r}，应为closure_pending"}
    return {"score": 1, "detail": "目标投诉已进入行政销号审批待办，未直接关闭"}


def check_historical_actions_unchanged(ws):
    with _connect(ws) as connection:
        rows = connection.execute(
            """SELECT action_id, actor_person_id, action_type, action_at, action_status,
                      conclusion_code, superseded_action_id, action_note
               FROM case_actions
               WHERE case_id = ? AND action_id IN ({})""".format(",".join("?" for _ in BASELINE_ACTION_IDS)),
            (CASE_ID, *sorted(BASELINE_ACTION_IDS)),
        ).fetchall()
    actual = {
        row["action_id"]: tuple(row[key] for key in (
            "actor_person_id", "action_type", "action_at", "action_status",
            "conclusion_code", "superseded_action_id", "action_note",
        ))
        for row in rows
    }
    if actual != BASELINE_HISTORY:
        changed = sorted(set(BASELINE_HISTORY) ^ set(actual))
        if not changed:
            changed = sorted(key for key in BASELINE_HISTORY if BASELINE_HISTORY[key] != actual.get(key))
        return {"score": 0, "detail": "既有历史动作被删除或修改：" + "、".join(changed)}
    return {"score": 1, "detail": "六条既有历史动作保持不变"}


def check_unrelated_records_unchanged(ws):
    queries = {
        "other_cases": ("SELECT * FROM noise_cases WHERE case_id <> ? ORDER BY case_id", (CASE_ID,)),
        "other_actions": ("SELECT * FROM case_actions WHERE case_id <> ? ORDER BY action_id", (CASE_ID,)),
        "assignments": ("SELECT * FROM case_assignments ORDER BY assignment_id", ()),
        "personnel": ("SELECT * FROM case_personnel ORDER BY person_id", ()),
    }
    with _connect(ws) as connection:
        actual = {name: _digest_rows(connection, sql, params) for name, (sql, params) in queries.items()}
    changed = [name for name, expected in UNRELATED_DIGESTS.items() if actual.get(name) != expected]
    if changed:
        return {"score": 0, "detail": "无关记录发生变化：" + "、".join(changed)}
    return {"score": 1, "detail": "其他投诉、动作、任务分工和人员记录保持不变"}
